import { useCallback } from "react";
import { useEditorRef, useEditorSelector } from "platejs/react";

/**
 * Subscribe to editor history (undo/redo) availability.
 *
 * Must be used inside a `<RichText>` (or `<Plate>`) context.
 *
 * @param editorId - Optional editor ID when multiple editors exist under a `PlateController`
 * @returns `{ canUndo, canRedo, undo, redo }`
 *
 * @example
 * const history = useHistoryState();
 * <IconButton disabled={!history.canUndo} onClick={history.undo}>Undo</IconButton>
 */
export function useHistoryState(editorId?: string) {
  const editor = useEditorRef();
  const selectorOptions = editorId ? { id: editorId } : undefined;

  const canUndo = useEditorSelector(
    (ed) => !!ed?.history?.undos?.length,
    [],
    ...(selectorOptions ? [selectorOptions] : []),
  );
  const canRedo = useEditorSelector(
    (ed) => !!ed?.history?.redos?.length,
    [],
    ...(selectorOptions ? [selectorOptions] : []),
  );

  const undo = useCallback(() => {
    editor.tf.undo();
    editor.tf.focus();
  }, [editor]);

  const redo = useCallback(() => {
    editor.tf.redo();
    editor.tf.focus();
  }, [editor]);

  return { canUndo, canRedo, undo, redo };
}
